var THREE_CAREERS = "Magistratura, Minist\xE9rio P\xFAblico e Defensoria P\xFAblica";
var AXIS = /lei\s*seca|doutrina|jurisprud/i;
var PENALTY = /\b(pena|reclus[aã]o|deten[cç][aã]o|multa|prescri[cç][aã]o|honor[aá]ri|al[ií]quota|juros|selic|sal[aá]rio|reduz|aument|diminui|major|atenu|metade|ter[cç]o|dobro|triplo)\b/i;
var TAX_BASE = /hip[oó]tese de incid[eê]ncia|base de c[aá]lculo/i;
