// ../src/lib/authPolicy.ts
var EMAIL_RE = /^[a-z0-9._%+-]+@[a-z0-9.-]+\.[a-z]{2,}$/i;
function normalizeEmail(value) {
  if (typeof value !== "string") return null;
  const email = value.trim().toLowerCase();
  if (email.length < 6 || email.length > 200 || !EMAIL_RE.test(email)) return null;
  return email;
}
function sanitizeDisplayName(value) {
  if (typeof value !== "string") return null;
  const name = value.replace(/[<>"'`\\]/g, "").replace(/[\u0000-\u001F\u007F]/g, "").replace(/\s+/g, " ").trim();
  if (name.length < 3 || name.length > 80) return null;
  return name;
}
function validatePassword(password, email) {
  if (typeof password !== "string") return "Informe uma senha.";
  if (password.length < 10 || password.length > 72) {
    return "A senha precisa ter entre 10 e 72 caracteres.";
  }
  if (!/[A-Za-z]/.test(password) || !/[0-9]/.test(password)) {
    return "A senha precisa ter letras e n\xFAmeros.";
  }
  if (email && password.toLowerCase().includes(email.toLowerCase())) {
    return "A senha n\xE3o pode conter o e-mail.";
  }
  return null;
}

// ../src/services/passwordHash.ts
import bcrypt from "bcryptjs";
import { randomInt } from "crypto";
var BCRYPT_ROUNDS = 12;
var UPPER = "ABCDEFGHJKLMNPQRSTUVWXYZ";
var LOWER = "abcdefghijkmnopqrstuvwxyz";
var DIGITS = "23456789";
var ALL = UPPER + LOWER + DIGITS;
function generateTemporaryPassword(length = 16) {
  const chars = [
    UPPER[randomInt(UPPER.length)],
    LOWER[randomInt(LOWER.length)],
    DIGITS[randomInt(DIGITS.length)]
  ];
  while (chars.length < length) chars.push(ALL[randomInt(ALL.length)]);
  for (let i = chars.length - 1; i > 0; i--) {
    const j = randomInt(i + 1);
    const swap = chars[i];
    chars[i] = chars[j];
    chars[j] = swap;
  }
  return chars.join("");
}
async function hashPassword(password) {
  return bcrypt.hash(password, BCRYPT_ROUNDS);
}
async function verifyPassword(password, passwordHash) {
  if (!password || !passwordHash) return false;
  return bcrypt.compare(password, passwordHash);
}

