  const idToken = String(created.idToken || "");
  const uid = String(created.localId || "");
  if (!uid || !idToken) throw new AuthFlowError("AUTH_FAILED");
  await identityPost("accounts:update", { idToken, displayName: name }).catch(() => void 0);
  return { uid, idToken };
