          const ref = db.collection(REVIEWS).doc(reviewId);
          const snap = await tx.get(ref);
          const review = asReview(snap.exists ? snap.data() : void 0);
          if (!review || review.status !== "pending_approval") {
            throw new LegalReviewError("Esta revis\xE3o n\xE3o est\xE1 aguardando aprova\xE7\xE3o.", 409);
          }
          if (!review.supplement) {
            throw new LegalReviewError("Esta revis\xE3o n\xE3o possui complementa\xE7\xE3o jur\xEDdica para encerrar.", 404);
          }
          const currentCandidateHash = (review.candidateHash || "").trim().toLowerCase();
          const currentDecisionStateHash = computeDecisionStateHash(review).toLowerCase();
          if (review.supplement.resolution && review.supplement.resolution.status === "RESOLVIDO_PELO_CEO") {
            const res = review.supplement.resolution;
            const sameCandidate = res.candidateHashAtClosure === review.candidateHash;
            const sameDecisions = Boolean(res.decisionStateHashAtClosure && res.decisionStateHashAtClosure === currentDecisionStateHash);
            const noNewAddenda = !(review.addenda && review.addenda.some((a) => a.createdAt > res.closedAt));
            if (sameCandidate && sameDecisions && noNewAddenda) {
              throw new LegalReviewError(
                "A complementa\xE7\xE3o jur\xEDdica j\xE1 foi encerrada anteriormente pelo CEO para esta mesma vers\xE3o do texto candidato e delibera\xE7\xF5es.",
                409
              );
            }
          }
          if (expectedHashes) {
            const expCandHash = (expectedHashes.expectedCandidateHash || "").trim().toLowerCase();
            const expDecHash = (expectedHashes.expectedDecisionStateHash || "").trim().toLowerCase();
            if (!expCandHash) {
              throw new LegalReviewError("O hash esperado do candidato (expectedCandidateHash) \xE9 obrigat\xF3rio.", 400);
            }
            if (!/^[a-f0-9]{64}$/i.test(expCandHash)) {
              throw new LegalReviewError(
                "O formato de expectedCandidateHash \xE9 inv\xE1lido (deve ser SHA-256 hexadecimal com 64 caracteres).",
                400
              );
            }
            if (!expDecHash) {
              throw new LegalReviewError("O hash esperado do estado de delibera\xE7\xF5es (expectedDecisionStateHash) \xE9 obrigat\xF3rio.", 400);
            }
            if (!/^[a-f0-9]{64}$/i.test(expDecHash)) {
              throw new LegalReviewError(
                "O formato de expectedDecisionStateHash \xE9 inv\xE1lido (deve ser SHA-256 hexadecimal com 64 caracteres).",
                400
              );
            }
            if (currentCandidateHash && expCandHash !== currentCandidateHash) {
              throw new LegalReviewError(
                "A revis\xE3o jur\xEDdica foi modificada desde o carregamento da p\xE1gina. O texto candidato atual difere da vers\xE3o visualizada. Recarregue a p\xE1gina antes de encerrar.",
                409
              );
            }
            if (expDecHash !== currentDecisionStateHash) {
              throw new LegalReviewError(
                "O estado das delibera\xE7\xF5es individuais foi modificado desde o carregamento da p\xE1gina. As decis\xF5es registradas diferem da vers\xE3o visualizada. Recarregue a p\xE1gina antes de encerrar.",
                409
              );
            }
          }
          const check = validateFindingsForClosure(review);
          if (!check.ok) {
            throw new LegalReviewError(
              `O encerramento da complementa\xE7\xE3o foi rejeitado porque existem pend\xEAncias n\xE3o resolvidas:
- ${check.failureReasons.join("\n- ")}`,
              400
            );
          }
          if ((resolution.overallJustification || "").trim().length < 15) {
            throw new LegalReviewError(
              "A justificativa global de encerramento da complementa\xE7\xE3o pelo CEO \xE9 insuficiente (m\xEDnimo de 15 caracteres).",
              400
            );
          }
          const priorResolution = review.supplement.resolution;
          const priorHistory = [...priorResolution?.history || []];
          if (priorResolution && (priorResolution.candidateHashAtClosure !== review.candidateHash || priorResolution.decisionStateHashAtClosure !== currentDecisionStateHash || review.addenda && review.addenda.some((a) => a.createdAt > priorResolution.closedAt))) {
            priorHistory.push({
              status: priorResolution.status,
              closedAt: priorResolution.closedAt,
              closedByUid: priorResolution.closedByUid,
              closedByEmail: priorResolution.closedByEmail,
              overallJustification: priorResolution.overallJustification,
              candidateHashAtClosure: priorResolution.candidateHashAtClosure,
              decisionStateHashAtClosure: priorResolution.decisionStateHashAtClosure,
              totalFindingsResolved: priorResolution.totalFindingsResolved
            });
          }
          const updatedSupplement = {
            ...review.supplement,
            resolution: {
              ...resolution,
              candidateHashAtClosure: review.candidateHash,
              decisionStateHashAtClosure: currentDecisionStateHash,
              closedAt: now,
              history: priorHistory
            }
          };
          const updated = {
            ...review,
            supplement: updatedSupplement
          };
          tx.set(ref, {
            supplement: updatedSupplement
          }, { merge: true });
