async function getLatestLegalReviewFlow(repo, input) {
  const scopeId = typeof input.blockIndex === "number" ? sectionReviewKey(input.day, input.part, input.blockIndex) : lessonDocId(input.day, input.part);
  const catalogId = lessonDocId(input.day, input.part);
  const lesson = await repo.getLesson(catalogId);
  if (!lesson) {
    return { found: false };
  }
  let expectedHash = "";
  if (typeof input.blockIndex === "number") {
    const slice = extractCatalogBlock(lesson.content, input.blockIndex);
    if (!slice) return { found: false };
    const sectionLesson = { ...lesson, id: scopeId, content: slice };
    expectedHash = hashCatalogSnapshot(sectionLesson);
  } else {
    expectedHash = hashCatalogSnapshot(lesson);
  }
  const index = await repo.getIndex(scopeId);
  if (!index || !index.latestReviewId) {
    return { found: false };
  }
  const review = await repo.get(index.latestReviewId);
  if (!review || review.testMode || review.lessonId !== scopeId) {
    return { found: false };
  }
  const matchesOriginal = review.originalHash === expectedHash;
  let conflict = false;
  if (review.reconciliation) {
    const check = validateReconciliationIntegrity(review, expectedHash);
    conflict = !check.valid && !matchesOriginal;
  } else {
    conflict = !matchesOriginal;
  }
  return {
    found: true,
    review: publicReview(review),
    conflict,
    status: review.status,
    catalogHash: expectedHash
  };
}
